/** Fee-defaulter prediction (S3). One row per family per night. */
export const defaulterScores = defineTable(
  'defaulter_scores',
  { module: 'M44', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    scoreDate: dateStr().notNull(),
    /** the likelihood of paying late next month */
    score: integer().notNull(),
    band: enumText(defaulterScoreBands).notNull(),
    /** late payments in the last 6 months, average days late, part payments, broken promises, open balance in months */
    factors: jsonb().notNull(),
    suggestedAction: enumText(defaulterScoreSuggestedActions).notNull(),
  },
  (t) => [
    between('defaulter_scores', t.score, 0, 100),
    uniqueIndex('defaulter_scores_family_score_date_uq').on(t.familyId, t.scoreDate).where(live(t)),
  ],
);

/** How well a section, and each student, has done on each syllabus topic (S2), from marks tagged with topics. */
export const topicMastery = defineTable(
  'topic_mastery',
  { module: 'M44', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    gradeSubjectId: uuid()
      .references((): AnyPgColumn => gradeSubjects.id)
      .notNull(),
    unitId: uuid()
      .references((): AnyPgColumn => syllabusUnits.id)
      .notNull(),
    sectionId: uuid()
      .references((): AnyPgColumn => sections.id)
      .notNull(),
    /** empty for the section's figure */
    studentId: uuid().references((): AnyPgColumn => students.id),
    marksObtained: decimal(8, 2).notNull(),
    marksAvailable: decimal(8, 2).notNull(),
    /** weighted so recent papers count more */
    masteryPercent: decimal(5, 2).notNull(),
    papersCounted: integer().notNull(),
    updatedOn: dateStr().notNull(),
  },
  (t) => [
    positive('topic_mastery', t.marksAvailable),
    uniqueIndex('topic_mastery_section_unit_student_uq')
      .on(
        t.sectionId,
        t.unitId,
        sql`coalesce(${t.studentId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

/** Unusual activity (S5): something a rule noticed that a person should look at. */
export const activityFlags = defineTable(
  'activity_flags',
  { module: 'M44', scope: 'org' },
  {
    ...baseColumns,
    /** from the rule list in §4 */
    ruleKey: text().notNull(),
    branchId: uuid().references((): AnyPgColumn => branches.id),
    severity: enumText(activityFlagSeverities).notNull(),
    /** `staff`, `cash_session`, `fee_payment`, `discount`, `vendor`, `payslip`, `stock_item`, `user` */
    subjectType: text().notNull(),
    subjectId: uuid().notNull(),
    /** the figures that triggered it and the norm they were compared with */
    detail: jsonb().notNull(),
    periodFrom: dateStr().notNull(),
    periodTo: dateStr().notNull(),
    status: enumText(activityFlagStatuses).notNull().default('open'),
    reviewedBy: uuid().references((): AnyPgColumn => profiles.id),
    reviewNote: text(),
  },
  (t) => [
    uniqueIndex('activity_flags_rule_key_subject_type_subject_period_from_uq')
      .on(t.ruleKey, t.subjectType, t.subjectId, t.periodFrom)
      .where(live(t)),
  ],
);
